body:
{
  "pains": [
    {
      "id": "pain:cant-find-anything",
      "statement": "Our workspace turned into a digital junk drawer and search became useless, so I ask a person instead of looking.",
      "element": "b2b:ease_of_doing_business:information",
      "shape": {
        "surface": "Search returns duplicates, Untitled pages and stale copies; the right page never shows up first.",
        "operational": "People re-ask questions in Slack, rebuild docs that already exist, and lose time hunting through nested pages.",
        "personal": "They stop trusting the tool they are paying for and feel stupid for not finding a page they know exists.",
        "personal_note": "Personal cost read from the junk-drawer and 1,000+ bookmarks posts; no source states the feeling outright."
      },
      "workflow": "Mid-task in Notion, someone types into Notion search or Ctrl+K to find a spec, SOP or saved article, scrolls a list of duplicates and Untitled pages, then gives up and pings a teammate in Slack.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {"event": "Workspace passes thousands of pages with duplicates and deep nesting", "cites": ["src:8"]},
        {"event": "Saving articles and bookmarks into Notion faster than anyone organizes them", "cites": ["src:21"]}
      ],
      "who_feels": ["end_user", "champion"],
      "by_role": {
        "end_user": {
          "says": [
            {"situation": "venting", "verbatim": "I had 1,000+ bookmarks in Chrome and Notion but could never find the specific article I needed", "cites": ["src:21"]},
            {"situation": "when_comparing", "verbatim": "Compared to search functions in other tools it's probably near the top. I'm looking at you Notion…", "cites": ["src:22"]}
          ],
          "costs_them": "Minutes per lookup, many times a day, plus duplicate work when they give up and rewrite.",
          "fears": "Acting on the wrong version of a doc because the right one never surfaced.",
          "dream_outcome": "Ask a question and get the current answer with the page it came from."
        },
        "champion": {
          "says": [
            {"situation": "when_it_bites", "verbatim": "Search became useless.", "cites": ["src:8"]}
          ],
          "costs_them": "Their credibility as the person who brought Notion in.",
          "fears": "The team quietly drifts back to Google Docs and Slack threads.",
          "dream_outcome": "The workspace is the first place people look and it answers them."
        }
      },
      "relief": {
        "line": "Found on the first try. Search or Ask returns the live page, not five copies.",
        "says": [],
        "gap": "Looked across Trustpilot, HN and Product Hunt; complainers describe the broken state, none described the fixed one in their own words."
      },
      "euphoria": {
        "line": "One place for everything. The workspace becomes the daily default for anything.",
        "says": [
          {"role": "end_user", "verbatim": "It's my day-to-day product for pretty much anything.", "cites": ["src:30"]}
        ],
        "gap": null
      },
      "segments": ["seg:startup", "seg:enterprise", "seg:individual"],
      "feature_ref": "feat:kb",
      "cites": ["src:8", "src:21", "src:22"],
      "priority": 1,
      "felt_evidence": {
        "kind": "building",
        "what": "A maker built and launched a read-only Notion Health Check in Dec 2025 to find orphan pages, duplicates and stale content after search stopped working.",
        "cites": ["src:8"]
      },
      "revealed_by": null
    },
    {
      "id": "pain:workspace-cleanup-tax",
      "statement": "Someone has to own restructuring the mess of pages, teamspaces and databases, and nobody has the hours, so we end up hiring for it.",
      "element": "b2b:ease_of_doing_business:organization",
      "shape": {
        "surface": "Teamspaces, calendars and databases built ad hoc by different people with no shared naming or hierarchy.",
        "operational": "Ops or IT pays a consultant or full-time admin to audit and rebuild, then the sprawl grows back.",
        "personal": null,
        "personal_note": "Job posts state the business need; no source shows what it costs the ops person personally."
      },
      "workflow": "An ops lead or chief of staff opens the Notion sidebar, finds duplicate teamspaces and abandoned databases, and posts a job on onlinejobs.ph, Upwork or Fiverr to audit and rebuild the workspace.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {"event": "Workspace grows to multiple teamspaces, calendars and databases built by different people", "cites": ["src:9"]}
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {"situation": "when_looking", "verbatim": "multiple pages, teamspaces, calendars, and databases that need restructuring, clean-up, and optimization", "cites": ["src:9"]}
          ],
          "costs_them": "A paid contractor or admin headcount on top of the Notion seats.",
          "fears": "Paying for a rebuild that decays back into sprawl in six months.",
          "dream_outcome": "A workspace that stays clean without a person babysitting it."
        },
        "champion": {
          "says": [
            {"situation": "venting", "verbatim": "a digital junk drawer", "cites": ["src:8"]}
          ],
          "costs_them": "Nights spent auditing pages instead of their real job.",
          "fears": "Being blamed for the mess they introduced.",
          "dream_outcome": "Stale and orphan pages get flagged and archived automatically."
        }
      },
      "relief": {
        "line": "Clean and easy to navigate. The rebuilt workspace is obvious to a new hire.",
        "says": [
          {"role": "economic_buyer", "verbatim": "a visually clean, intuitive, and scalable environment", "cites": ["src:9"]}
        ],
        "gap": null
      },
      "euphoria": {
        "line": "It stays tidy. A year on nobody is hiring a second cleanup.",
        "says": [],
        "gap": "No buyer found describing a workspace that stayed clean a year later; job posts only describe the target state."
      },
      "segments": ["seg:startup", "seg:enterprise"],
      "feature_ref": null,
      "feature_note": "An agent that audits and archives stale, duplicate and orphan pages would; Notion AI and agents (feat:ai) could do it but brain/company does not claim it.",
      "cites": ["src:8", "src:9"],
      "priority": 2,
      "felt_evidence": {
        "kind": "hiring",
        "what": "A Sep 2026 onlinejobs.ph post hires a Notion expert full-time specifically to restructure and clean up an existing workspace.",
        "cites": ["src:9"]
      },
      "revealed_by": null
    },
    {
      "id": "pain:slow-at-scale",
      "statement": "Notion gets slower with every page we add, and now opening a database means waiting.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "Pages and databases lag on load, in Firefox and on high-end laptops alike.",
        "operational": "Dashboards with linked databases stall the daily standup and status checks; people avoid opening them.",
        "personal": "Forced users resent a tool they did not choose.",
        "personal_note": "Read from 'We have to use Notion at work'."
      },
      "workflow": "Opening a project dashboard or CRM database in the Notion web or desktop app before standup and waiting for linked views, relations and rollups to load.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {"event": "Workspace or database grows past a few thousand pages", "cites": ["src:13"]},
        {"event": "Company mandates Notion for everyone", "cites": ["src:14"]}
      ],
      "who_feels": ["end_user", "blocker"],
      "by_role": {
        "end_user": {
          "says": [
            {"situation": "venting", "verbatim": "We have to use Notion at work, it's slow, bloated, and not a great UI experience overall.", "cites": ["src:14"]},
            {"situation": "when_it_bites", "verbatim": "why is Notion so slow on Firefox? I mean extremely slow.", "cites": ["src:26"]},
            {"situation": "venting", "verbatim": "It can be really useful when it works properly, but the problem is its often slow or goes down", "cites": ["src:6"]}
          ],
          "costs_them": "Seconds per page load, across every page, every day.",
          "fears": "It only gets worse as the company adds more.",
          "dream_outcome": "Pages open instantly no matter how big the workspace gets."
        },
        "blocker": {
          "says": [
            {"situation": "when_refusing", "verbatim": "I think notion's big failure is how slow it is.", "cites": ["src:15"]},
            {"situation": "when_refusing", "verbatim": "Please fix how slow notion is before expanding your brand.", "cites": ["src:25"]}
          ],
          "costs_them": "Time arguing for a faster tool.",
          "fears": "Being stuck with a sluggish tool the whole company standardized on.",
          "dream_outcome": "Speed fixed before new features ship."
        }
      },
      "relief": {
        "line": "It just loads. Big databases open as fast as a small page.",
        "says": [],
        "gap": "Searched HN and Trustpilot; no buyer wrote about Notion becoming fast."
      },
      "euphoria": {
        "line": "Grows without slowing. Adding the 10,000th page costs nothing.",
        "says": [],
        "gap": "No public account found of a large workspace that stayed fast."
      },
      "segments": ["seg:startup", "seg:enterprise", "seg:individual"],
      "feature_ref": null,
      "feature_note": "Engine performance work, not a listed feature in brain/company.",
      "cites": ["src:6", "src:12", "src:13", "src:14", "src:15", "src:25", "src:26"],
      "priority": 3,
      "felt_evidence": {
        "kind": "building",
        "what": "An HN user built their own replacement in May 2026, saying they built it because Notion is way too slow.",
        "cites": ["src:12"]
      },
      "revealed_by": null
    },
    {
      "id": "pain:setup-tax",
      "statement": "I spend more time building my Notion system than doing the things it's meant to track.",
      "element": "b2c:functional:simplifies",
      "shape": {
        "surface": "Blank pages, endless templates and block choices before anything useful exists.",
        "operational": "Hours go into designing databases and dashboards; the setup gets abandoned and rebuilt.",
        "personal": "They feel lost and blame themselves for not being organized enough.",
        "personal_note": "From 'Notion Broke My Brain' review."
      },
      "workflow": "An individual opens a fresh Notion workspace to plan their life or work, browses templates, builds databases and a homepage, and three hours later has a system but no tasks done.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {"event": "Starting fresh in Notion to get organized", "cites": ["src:5"]}
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {"situation": "venting", "verbatim": "Tried to use Notion to get organized. Ended up lost in a maze of templates, blocks, and empty pages.", "cites": ["src:5"]},
            {"situation": "when_it_bites", "verbatim": "I have watched people spend more time building their Notion setup than actually doing the tasks the setup was meant to track.", "cites": ["src:10"]}
          ],
          "costs_them": "Evenings of setup that never pay back.",
          "fears": "Another abandoned system and proof they can't stay organized.",
          "dream_outcome": "A setup that works on day one so they can just use it."
        }
      },
      "relief": {
        "line": "Part of the routine. It works without more tinkering.",
        "says": [
          {"role": "end_user", "verbatim": "Been using Notion for about 3 months now and honestly it's become part of my daily routine.", "cites": ["src:32"]}
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Life runs in one place. Years later it still holds work and personal life.",
        "says": [
          {"role": "end_user", "verbatim": "Notion has been a game-changer for organising both my personal workflow and our company projects.", "cites": ["src:31"]}
        ],
        "gap": null
      },
      "segments": ["seg:individual"],
      "feature_ref": null,
      "feature_note": "Notion AI and agents (feat:ai) could build the setup for them, but brain/company does not claim setup-building.",
      "cites": ["src:5", "src:10"],
      "priority": 4,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Oct 2025 Trustpilot review 'Notion Broke My Brain' and a Jan 2026 blog both describe the setup eating the work.",
        "cites": ["src:5", "src:10"]
      },
      "revealed_by": null
    },
    {
      "id": "pain:surprise-ai-credits",
      "statement": "We already pay for Business and then find out the agents need extra credits on top.",
      "element": "b2b:table_stakes:acceptable_price",
      "shape": {
        "surface": "Custom Agent runs draw on credits sold only to Business and Enterprise, on top of the seat price.",
        "operational": "Monthly spend becomes unpredictable; finance sees a second line item for AI.",
        "personal": "The buyer feels misled after moving their work in.",
        "personal_note": "From 'very misleading' and 'Absolute trash' reviews."
      },
      "workflow": "An admin turns on Custom Agents in Notion settings, agents start running on schedules, and the admin gets a prompt or invoice to buy more Notion credits.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {"event": "First prompt to buy extra credits after already paying for a Business plan", "cites": ["src:2", "src:3"]}
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {"situation": "venting", "verbatim": "You pay 200 euros per month to have access to everything and then you find out that you need to buy extra credits", "cites": ["src:2"]},
            {"situation": "venting", "verbatim": "The product is ok when it works, but paying for a business account with extra credits beyond that", "cites": ["src:3"]},
            {"situation": "when_refusing", "verbatim": "This company has a clear strategy of reaping as much money out of promised AI features as they can", "cites": ["src:7"]}
          ],
          "costs_them": "An open-ended AI bill on top of seats.",
          "fears": "Agents running up credits nobody approved.",
          "dream_outcome": "One predictable price that includes the AI they were sold."
        }
      },
      "relief": {
        "line": "No surprise line items. The agent bill is known before the month starts.",
        "says": [],
        "gap": "Trustpilot and HN show only the complaint; no buyer described a predictable AI bill."
      },
      "euphoria": {
        "line": "AI pays for itself. Agent spend is a clear trade against hours saved.",
        "says": [],
        "gap": "No public buyer account ties credit spend to time saved."
      },
      "segments": ["seg:startup", "seg:enterprise"],
      "feature_ref": null,
      "feature_note": "Pricing and spend controls, not a product feature in brain/company.",
      "cites": ["src:2", "src:3", "src:7", "src:24"],
      "priority": 5,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Trustpilot reviews dated Sep 14 and Oct 3, 2026 complain about paying for Business and then buying credits.",
        "cites": ["src:2", "src:3"]
      },
      "revealed_by": null
    },
    {
      "id": "pain:ai-in-my-data",
      "statement": "I didn't ask for AI in my files, I can't switch it off, and I don't know where my data goes.",
      "element": "b2b:table_stakes:regulatory_compliance",
      "shape": {
        "surface": "AI features show up across the product with no built-in off switch.",
        "operational": "Security and legal have to vet data flows to AI vendors before the team can keep using it.",
        "personal": "Users feel their private notes are no longer private.",
        "personal_note": "From 'I don't want it anywhere near my own files' context in src:11."
      },
      "workflow": "A user or admin notices AI prompts inside pages and settings, looks for a toggle, finds none, and emails support or starts an export to Obsidian.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {"event": "Learning workspace content was sent to a third-party AI provider", "cites": ["src:4"]},
        {"event": "AI features added across the product with no off switch", "cites": ["src:11"]}
      ],
      "who_feels": ["blocker", "end_user"],
      "by_role": {
        "blocker": {
          "says": [
            {"situation": "when_refusing", "verbatim": "Turns out notion was sending all of our proprietary business data to OpenAI.", "cites": ["src:4"]}
          ],
          "costs_them": "A security review and possible migration.",
          "fears": "Proprietary data leaving the company without approval.",
          "dream_outcome": "Admin-level control over which AI touches which data."
        },
        "end_user": {
          "says": [
            {"situation": "when_refusing", "verbatim": "there is no way to turn it off built into the default program.", "cites": ["src:11"]},
            {"situation": "venting", "verbatim": "Notion will continue to be slow and clunky and full of AI shit nobody wants.", "cites": ["src:17"]}
          ],
          "costs_them": "Leaving a tool they liked.",
          "fears": "Their personal notes training or feeding someone else's model.",
          "dream_outcome": "AI is opt-in and clearly fenced off."
        }
      },
      "relief": {
        "line": "AI on my terms. It's off until I or my admin turn it on.",
        "says": [],
        "gap": "Only refusals found; no user described being satisfied with AI controls."
      },
      "euphoria": {
        "line": "Trusted with everything. They put sensitive work in without a second thought.",
        "says": [],
        "gap": "No source found."
      },
      "segments": ["seg:individual", "seg:enterprise"],
      "feature_ref": null,
      "feature_note": "Admin AI and data controls; not listed in brain/company.",
      "cites": ["src:4", "src:11", "src:17"],
      "priority": 6,
      "felt_evidence": {
        "kind": "switching",
        "what": "A July 2025 blog post documents leaving Notion for Obsidian because AI was added everywhere with no built-in off switch.",
        "cites": ["src:11"]
      },
      "revealed_by": null
    },
    {
      "id": "pain:docs-go-dead",
      "statement": "Once something goes into the wiki nobody looks at it again, and wrong docs are worse than none.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "Wiki pages written once and never updated.",
        "operational": "Teams act on outdated process docs; onboarding teaches the wrong thing.",
        "personal": null,
        "personal_note": "No source describes the personal cost."
      },
      "workflow": "A team writes a process page in the Notion wiki after a project, nobody revisits it, and months later a new hire or Notion AI answer pulls from the stale page.",
      "type": "latent",
      "confidence": "low",
      "triggers": [
        {"event": "An AI answer or new hire relies on a page that is months out of date", "cites": ["src:23"]}
      ],
      "who_feels": ["champion", "end_user"],
      "by_role": {
        "champion": {
          "says": [
            {"situation": "venting", "verbatim": "Most people don't ever look into notion or a wiki ever again and everything that's being put in there is basically dead", "cites": ["src:23"]}
          ],
          "costs_them": "The wiki they championed becomes a graveyard.",
          "fears": "Someone follows a dead doc and breaks something.",
          "dream_outcome": "Docs that flag themselves when they go stale."
        }
      },
      "relief": {
        "line": "Docs stay current. Stale pages get flagged before anyone uses them.",
        "says": [],
        "gap": "Only one dated HN comment found; no buyer described the fixed state."
      },
      "euphoria": {
        "line": "The wiki is trusted. People cite it instead of asking around.",
        "says": [],
        "gap": "No source found."
      },
      "segments": ["seg:startup", "seg:enterprise"],
      "feature_ref": "feat:kb",
      "cites": ["src:8", "src:23"],
      "priority": 7,
      "felt_evidence": null,
      "revealed_by": "feat:ai"
    },
    {
      "id": "pain:offline-brick",
      "statement": "Without a connection Notion is useless, so I can't rely on it on a plane or a bad network.",
      "element": "b2b:ease_of_doing_business:availability",
      "shape": {
        "surface": "Limited offline mode and a weaker mobile app.",
        "operational": "People keep a second notes app for travel and phones, splitting their knowledge.",
        "personal": "Anxiety that their only copy lives in someone else's cloud.",
        "personal_note": "From j45's comment on data living only in the app's cloud."
      },
      "workflow": "Opening Notion on a phone or laptop while traveling or on weak Wi-Fi, finding pages won't load, and falling back to Apple Notes or Obsidian.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {"event": "Needing notes with no or weak internet, often on mobile", "cites": ["src:18", "src:19"]}
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {"situation": "venting", "verbatim": "My biggest gripe with Notion is that it doesn't work offline.", "cites": ["src:18"]},
            {"situation": "when_comparing", "verbatim": "Notion combines them but it's slow and its offline capabilities are limited.", "cites": ["src:16"]},
            {"situation": "when_refusing", "verbatim": "But found the lack of offline support and the mobile app very limiting.", "cites": ["src:19"]}
          ],
          "costs_them": "Running two notes apps.",
          "fears": "Losing access to their own data.",
          "dream_outcome": "Everything available on any device, online or not."
        }
      },
      "relief": {
        "line": "Works anywhere. Pages open on a plane like at the desk.",
        "says": [],
        "gap": "No user found describing Notion offline working well."
      },
      "euphoria": {
        "line": "My data is mine. A local copy always exists.",
        "says": [
          {"role": "end_user", "verbatim": "The only copy of my data should not exist solely in an app’s cloud, and I should not need to manually export anything.", "cites": ["src:20"]}
        ],
        "gap": null
      },
      "segments": ["seg:individual"],
      "feature_ref": null,
      "feature_note": "An offline sync mode; not listed in brain/company.",
      "cites": ["src:16", "src:18", "src:19", "src:20"],
      "priority": 8,
      "felt_evidence": {
        "kind": "complaining",
        "what": "HN comments from Jun 2025 and Mar 2026 name lack of offline as the biggest gripe or a reason they passed.",
        "cites": ["src:16", "src:18"]
      },
      "revealed_by": null
    },
    {
      "id": "pain:priced-out-of-my-own-life",
      "statement": "I moved half my life into Notion and now the features I need cost too much.",
      "element": "b2c:functional:reduces_cost",
      "shape": {
        "surface": "Features individuals relied on move behind paid tiers.",
        "operational": "They pay, downgrade, or plan a painful export.",
        "personal": "Feeling trapped by their own data.",
        "personal_note": "From 'When you move to Notion half of your life' review."
      },
      "workflow": "A personal user hits a paywall on a feature inside a workspace holding years of notes, then weighs paying against exporting to another app.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {"event": "A feature they used moves to a paid plan after their life is already in Notion", "cites": ["src:27"]}
      ],
      "who_feels": ["end_user", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            {"situation": "venting", "verbatim": "When you move to Notion half of your life and then they decide to make it paid, not allowing to do anything", "cites": ["src:27"]},
            {"situation": "when_comparing", "verbatim": "I like the user experience but features are very expensive.", "cites": ["src:28"]}
          ],
          "costs_them": "A subscription they didn't plan for, or a migration.",
          "fears": "Being locked in as prices rise.",
          "dream_outcome": "A fair personal price that doesn't change under them."
        }
      },
      "relief": {
        "line": "Worth the price. They pay without resentment.",
        "says": [],
        "gap": "No individual described the price feeling fair after a change."
      },
      "euphoria": {
        "line": "Grows with me. Years in, it keeps getting better.",
        "says": [
          {"role": "end_user", "verbatim": "I really like Notion, been using Notion since 2019, and I can see it's getting more and more powerful.", "cites": ["src:29"]}
        ],
        "gap": null
      },
      "segments": ["seg:individual"],
      "feature_ref": null,
      "feature_note": "Pricing, not a feature.",
      "cites": ["src:27", "src:28"],
      "priority": 9,
      "felt_evidence": {
        "kind": "complaining",
        "what": "A Sep 21, 2026 Trustpilot review complains about features going paid after moving half their life in.",
        "cites": ["src:27"]
      },
      "revealed_by": null
    }
  ],
  "awareness": {
    "default": {
      "level": "product",
      "rationale": "Most public voices already use Notion and complain about specific behaviors of it (speed, search, credits), not about the problem in the abstract.",
      "cites": ["src:2", "src:14", "src:8"]
    },
    "seg:individual": {
      "level": "solution",
      "rationale": "Individuals compare Notion against Obsidian and Apple Notes and leave over offline and AI.",
      "cites": ["src:11", "src:19"]
    },
    "seg:enterprise": {
      "level": "most_aware",
      "rationale": "Admins buy Business plans, credits and hire Notion administrators; they know the product deeply.",
      "cites": ["src:9", "src:24"]
    }
  },
  "stats": [
    {
      "id": "stat:credits-business-only",
      "stat": "Notion credits for Custom Agents are only available on Business and Enterprise plans.",
      "scope": "Notion pricing, per Notion help center, pulled 2026-10-12",
      "cites": ["src:24"]
    },
